export const KIND = {"id":65,"example":{"id":"E65","kind":65,"source":"aether","statement":["Write a function `digit_cipher::encode(const std::string& text, int key)` that returns the digits of the text encoded with the key, a space between each 2.","Write a function `digit_cipher::decode(const std::string& text, int key)` that returns the digits of the text decoded with the same key, with no spaces.","Encoding turns digit d into the last digit of key × d. Decoding turns digit y into the last digit of x × y, where x is the number from 1 to 9 for which key × x ends in 1.","Both leave out every character that is not a digit.","Throw `std::invalid_argument` when 2 or 5 divides the key.","Limits: 1 ≤ key ≤ 99; 0 ≤ length of the text ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <cctype>","#include <stdexcept>","#include <string>","","namespace digit_cipher {","","void check_key(int key)","{","    if (key % 2 == 0 || key % 5 == 0) {","        throw std::invalid_argument {\"the key has no inverse\"};","    }","}","","int inverse(int key)","{","    int inverse {1};","    while (key * inverse % 10 != 1) {","        ++inverse;","    }","    return inverse;","}","","std::string apply_key(const std::string& text, int key)","{","    std::string result {\"\"};","    for (const char character : text) {","        if (std::isdigit(character)) {","            const int digit {(character - '0') * key % 10};","            result += static_cast<char>('0' + digit);","        }","    }","    return result;","}","","std::string spaced(const std::string& text)","{","    std::string result {\"\"};","    for (std::size_t index {0}; index < text.size(); ++index) {","        if (index > 0) {","            result += ' ';","        }","        result += text[index];","    }","    return result;","}","","std::string encode(const std::string& text, int key)","{","    check_key(key);","    return spaced(apply_key(text, key));","}","","std::string decode(const std::string& text, int key)","{","    check_key(key);","    return apply_key(text, inverse(key));","}","","}  // namespace digit_cipher"],"frame":[0,2,3,4,6,60],"labels":[{"at":8,"level":1,"text":"Write a function that throws an error when its input is not allowed."},{"at":15,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":17,"level":2,"text":"Start the inverse at 1."},{"at":18,"level":2,"text":"Add one to the inverse until the key times it leaves 1 after dividing by 10."},{"at":21,"level":2,"text":"Give back the inverse."},{"at":24,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":26,"level":2,"text":"Start the result as an empty string."},{"at":27,"level":2,"text":"For each digit, add the last digit of the digit times the key."},{"at":33,"level":2,"text":"Give back the result."},{"at":36,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":38,"level":2,"text":"Start the result as an empty string."},{"at":39,"level":2,"text":"For each character, add a space before all but the first, then the character."},{"at":45,"level":2,"text":"Give back the result."},{"at":48,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":54,"level":1,"text":"Write a function that calls the functions above and gives back the answer."}],"blanks":[]}},"trace":{"id":"T65","lines":["#include <iostream>","#include <print>","int inverse(int key)","{","    int inverse {1};","    while (key * inverse % 7 != 1) {","        ++inverse;","    }","    return inverse;","}","int main()","{","    int key {0};","    std::cin >> key;","    std::println(\"{}\", inverse(key));","}"],"columns":["key","inverse"],"inputs":["3\n","5\n"],"rows":[{"line":13,"values":["0",""]},{"line":14,"values":["3",""]},{"line":5,"values":["3","1"]},{"line":6,"values":["3","1"]},{"line":7,"values":["3","2"]},{"line":6,"values":["3","2"]},{"line":7,"values":["3","3"]},{"line":6,"values":["3","3"]},{"line":7,"values":["3","4"]},{"line":6,"values":["3","4"]},{"line":7,"values":["3","5"]},{"line":6,"values":["3","5"]},{"line":9,"values":["3","5"]},{"line":15,"values":["3",""]}],"output":"3\n"},"traces":[],"problems":{"65.01":{"id":"65.01","kind":65,"source":"exercism","statement":["Write a function `affine_cipher::encode(const std::string& input, int a, int b)` that returns the text encoded with the key a, b.","Write a function `affine_cipher::decode(const std::string& input, int a, int b)` that returns the text decoded with the same key.","Number the letters a = 0 to z = 25, in either case. Encoding turns letter number i into the lower-case letter number (a × i + b) mod 26.","Decoding turns letter number y into the letter number x × (y - b) mod 26, where x is the number from 1 to 25 for which a × x mod 26 is 1.","Both keep digits as they are and leave out every other character. Encoding then puts a space after every 5 characters, but not at the end.","Throw `std::invalid_argument` when a and 26 have a common divisor above 1.","Limits: 1 ≤ a ≤ 100; 0 ≤ b ≤ 100; 0 ≤ length of the text ≤ 1000."],"examples":[{"input":"encode_yes","output":""}],"tests":[{"input":"encode_no","output":""},{"input":"encode_OMG","output":""},{"input":"encode_O_M_G","output":""},{"input":"encode_mindblowingly","output":""},{"input":"encode_numbers","output":""},{"input":"encode_deep_thought","output":""},{"input":"encode_all_the_letters","output":""},{"input":"encode_with_a_not_coprime_to_m","output":""},{"input":"decode_exercism","output":""},{"input":"decode_a_sentence","output":""},{"input":"decode_numbers","output":""},{"input":"decode_all_the_letters","output":""},{"input":"decode_with_no_spaces_in_input","output":""},{"input":"decode_with_too_many_spaces","output":""},{"input":"decode_with_a_not_coprime_to_m","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <numeric>","#include <stdexcept>","#include <string>","","namespace affine_cipher {","","void check_key(int a)","{","    if (std::gcd(a, 26) != 1) {","        throw std::invalid_argument {\"a has no inverse\"};","    }","}","","int inverse(int a)","{","    int inverse {1};","    while (a * inverse % 26 != 1) {","        ++inverse;","    }","    return inverse;","}","","std::string apply_key(const std::string& text, int times,","    int plus)","{","    std::string result {\"\"};","    for (const char character : text) {","        if (std::isdigit(character)) {","            result += character;","        } else if (std::isalpha(character)) {","            const int index {std::tolower(character) - 'a'};","            const int moved {(times * index + plus) % 26};","            result += static_cast<char>('a' + moved);","        }","    }","    return result;","}","","std::string in_groups(const std::string& text)","{","    std::string result {\"\"};","    for (std::size_t index {0}; index < text.size(); ++index) {","        if (index > 0 && index % 5 == 0) {","            result += ' ';","        }","        result += text[index];","    }","    return result;","}","","std::string encode(const std::string& input, int a, int b)","{","    check_key(a);","    return in_groups(apply_key(input, a, b));","}","","std::string decode(const std::string& input, int a, int b)","{","    check_key(a);","    const int x {inverse(a)};","    return apply_key(input, x, x * (26 - b % 26));","}","","}  // namespace affine_cipher"],"frame":[0,2,3,4,5,7,66],"labels":[{"at":9,"level":1,"text":"Write a function that throws an error when its input is not allowed."},{"at":16,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":18,"level":2,"text":"Start the inverse at 1."},{"at":19,"level":2,"text":"Add one to the inverse until a times it leaves 1 after dividing by 26."},{"at":22,"level":2,"text":"Give back the inverse."},{"at":25,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":28,"level":2,"text":"Start the result as an empty string."},{"at":29,"level":2,"text":"For each character, add a digit as it is, and a letter moved by the key."},{"at":38,"level":2,"text":"Give back the result."},{"at":41,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":43,"level":2,"text":"Start the result as an empty string."},{"at":44,"level":2,"text":"For each character, add a space before it when 5, 10, 15 or more characters come before it, then the character."},{"at":50,"level":2,"text":"Give back the result."},{"at":53,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":59,"level":1,"text":"Write a function that calls the functions above and gives back the answer."}],"blanks":[{"line":9,"from":15,"to":20},{"line":16,"from":12,"to":17},{"line":18,"from":17,"to":18},{"line":19,"from":11,"to":32},{"line":22,"from":11,"to":18},{"line":25,"from":22,"to":45},{"line":28,"from":24,"to":26},{"line":32,"from":19,"to":42},{"line":38,"from":11,"to":17},{"line":41,"from":22,"to":45},{"line":43,"from":24,"to":26},{"line":45,"from":12,"to":39},{"line":50,"from":11,"to":17},{"line":53,"from":19,"to":57},{"line":59,"from":19,"to":57}]},"fn":{"slug":"affine-cipher","commit":"8d139cb0","header":"affine_cipher.h","name":"affine_cipher_test.cpp","test":"#include \"affine_cipher.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"encode_yes\", \"[2ee1d9af-1c43-416c-b41b-cefd7d4d2b2a]\") {\n    REQUIRE(affine_cipher::encode(\"yes\", 5, 7) == \"xbt\");\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"encode_no\", \"[785bade9-e98b-4d4f-a5b0-087ba3d7de4b]\") {\n    REQUIRE(affine_cipher::encode(\"no\", 15, 18) == \"fu\");\n}\n\nTEST_CASE(\"encode_OMG\", \"[2854851c-48fb-40d8-9bf6-8f192ed25054]\") {\n    REQUIRE(affine_cipher::encode(\"OMG\", 21, 3) == \"lvz\");\n}\n\nTEST_CASE(\"encode_O_M_G\", \"[bc0c1244-b544-49dd-9777-13a770be1bad]\") {\n    REQUIRE(affine_cipher::encode(\"O M G\", 25, 47) == \"hjp\");\n}\n\nTEST_CASE(\"encode_mindblowingly\", \"[381a1a20-b74a-46ce-9277-3778625c9e27]\") {\n    REQUIRE(affine_cipher::encode(\"mindblowingly\", 11, 15) ==\n            \"rzcwa gnxzc dgt\");\n}\n\nTEST_CASE(\"encode_numbers\", \"[6686f4e2-753b-47d4-9715-876fdc59029d]\") {\n    REQUIRE(affine_cipher::encode(\"Testing,1 2 3, testing.\", 3, 4) ==\n            \"jqgjc rw123 jqgjc rw\");\n}\n\nTEST_CASE(\"encode_deep_thought\", \"[ae23d5bd-30a8-44b6-afbe-23c8c0c7faa3]\") {\n    REQUIRE(affine_cipher::encode(\"Truth is fiction.\", 5, 17) ==\n            \"iynia fdqfb ifje\");\n}\n\nTEST_CASE(\"encode_all_the_letters\", \"[c93a8a4d-426c-42ef-9610-76ded6f7ef57]\") {\n    REQUIRE(affine_cipher::encode(\n                \"The quick brown fox jumps over the lazy dog.\", 17, 33) ==\n            \"swxtj npvyk lruol iejdc blaxk swxmh qzglf\");\n}\n\nTEST_CASE(\"encode_with_a_not_coprime_to_m\",\n          \"[0673638a-4375-40bd-871c-fb6a2c28effb]\") {\n    REQUIRE_THROWS_AS(affine_cipher::encode(\"This is a test.\", 6, 17),\n                      std::invalid_argument);\n}\n\nTEST_CASE(\"decode_exercism\", \"[3f0ac7e2-ec0e-4a79-949e-95e414953438]\") {\n    REQUIRE(affine_cipher::decode(\"tytgn fjr\", 3, 7) == \"exercism\");\n}\n\nTEST_CASE(\"decode_a_sentence\", \"[241ee64d-5a47-4092-a5d7-7939d259e077]\") {\n    REQUIRE(affine_cipher::decode(\"qdwju nqcro muwhn odqun oppmd aunwd o\", 19,\n                                  16) == \"anobstacleisoftenasteppingstone\");\n}\n\nTEST_CASE(\"decode_numbers\", \"[33fb16a1-765a-496f-907f-12e644837f5e]\") {\n    REQUIRE(affine_cipher::decode(\"odpoz ub123 odpoz ub\", 25, 7) ==\n            \"testing123testing\");\n}\n\nTEST_CASE(\"decode_all_the_letters\", \"[20bc9dce-c5ec-4db6-a3f1-845c776bcbf7]\") {\n    REQUIRE(affine_cipher::decode(\"swxtj npvyk lruol iejdc blaxk swxmh qzglf\",\n                                  17,\n                                  33) == \"thequickbrownfoxjumpsoverthelazydog\");\n}\n\nTEST_CASE(\"decode_with_no_spaces_in_input\",\n          \"[623e78c0-922d-49c5-8702-227a3e8eaf81]\") {\n    REQUIRE(affine_cipher::decode(\"swxtjnpvyklruoliejdcblaxkswxmhqzglf\", 17,\n                                  33) == \"thequickbrownfoxjumpsoverthelazydog\");\n}\n\nTEST_CASE(\"decode_with_too_many_spaces\",\n          \"[58fd5c2a-1fd9-4563-a80a-71cff200f26f]\") {\n    REQUIRE(affine_cipher::decode(\"vszzm    cly   yd cg    qdp\", 15, 16) ==\n            \"jollygreengiant\");\n}\n\nTEST_CASE(\"decode_with_a_not_coprime_to_m\",\n          \"[b004626f-c186-4af9-a3f4-58f74cdb86d5]\") {\n    REQUIRE_THROWS_AS(affine_cipher::decode(\"Test\", 13, 5),\n                      std::invalid_argument);\n}\n\n#endif\n","setup":[],"calls":[{"call":"affine_cipher::encode(\"yes\", 5, 7)","expected":"\"xbt\""}]}},"65.02":{"id":"65.02","kind":65,"source":"aether","statement":["Write a function `base36::encode(const std::string& text, int a, int b)` that returns the text encoded with the key a, b.","Write a function `base36::decode(const std::string& text, int a, int b)` that returns the text decoded with the same key.","Number the 36 symbols in this order: the letters a = 0 to z = 25, in either case, then the digits 0 = 26 to 9 = 35. Encoding turns symbol number i into the symbol number (a × i + b) mod 36, a letter in lower case.","Decoding turns symbol number y into the symbol number x × (y - b) mod 36, where x is the number from 1 to 35 for which a × x mod 36 is 1.","Both leave out every character that is not a letter or a digit. Encoding then puts a dash after every 4 characters, but not at the end.","Throw `std::invalid_argument` when 2 or 3 divides a.","Limits: 1 ≤ a ≤ 100; 0 ≤ b ≤ 100; 0 ≤ length of the text ≤ 1000; every character is ASCII."],"examples":[{"input":"encode_test","output":""}],"tests":[{"input":"encode_mixed_text","output":""},{"input":"encode_empty","output":""},{"input":"encode_large_key","output":""},{"input":"encode_long_text","output":""},{"input":"encode_wraps_to_the_start","output":""},{"input":"decode_test","output":""},{"input":"decode_with_dashes","output":""},{"input":"decode_long_text","output":""},{"input":"decode_empty","output":""},{"input":"encode_even_a_throws","output":""},{"input":"decode_three_divides_a_throws","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <numeric>","#include <stdexcept>","#include <string>","","namespace base36 {","","void check_key(int a)","{","    if (std::gcd(a, 36) != 1) {","        throw std::invalid_argument {\"a has no inverse\"};","    }","}","","int inverse(int a)","{","    int inverse {1};","    while (a * inverse % 36 != 1) {","        ++inverse;","    }","    return inverse;","}","","std::string apply_key(const std::string& text, int times,","    int plus)","{","    std::string result {\"\"};","    for (const char character : text) {","        if (std::isalnum(character)) {","            int index {std::tolower(character) - 'a'};","            if (std::isdigit(character)) {","                index = 26 + character - '0';","            }","            const int moved {(times * index + plus) % 36};","            if (moved < 26) {","                result += static_cast<char>('a' + moved);","            } else {","                result += static_cast<char>('0' + moved - 26);","            }","        }","    }","    return result;","}","","std::string in_groups(const std::string& text)","{","    std::string result {\"\"};","    for (std::size_t index {0}; index < text.size(); ++index) {","        if (index > 0 && index % 4 == 0) {","            result += '-';","        }","        result += text[index];","    }","    return result;","}","","std::string encode(const std::string& text, int a, int b)","{","    check_key(a);","    return in_groups(apply_key(text, a, b));","}","","std::string decode(const std::string& text, int a, int b)","{","    check_key(a);","    const int x {inverse(a)};","    return apply_key(text, x, x * (36 - b % 36));","}","","}  // namespace base36"],"frame":[0,2,3,4,5,7,71],"labels":[{"at":9,"level":1,"text":"Write a function that throws an error when its input is not allowed."},{"at":16,"level":1,"text":"Write a function that repeats a step until a condition holds and gives back the result."},{"at":18,"level":2,"text":"Start the inverse at 1."},{"at":19,"level":2,"text":"Add one to the inverse until a times it leaves 1 after dividing by 36."},{"at":22,"level":2,"text":"Give back the inverse."},{"at":25,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":28,"level":2,"text":"Start the result as an empty string."},{"at":29,"level":2,"text":"For each letter or digit, add the symbol the key moves it to."},{"at":43,"level":2,"text":"Give back the result."},{"at":46,"level":1,"text":"Write a function that builds a new string from each character of the text."},{"at":48,"level":2,"text":"Start the result as an empty string."},{"at":49,"level":2,"text":"For each character, add a dash before it when 4, 8, 12 or more characters come before it, then the character."},{"at":55,"level":2,"text":"Give back the result."},{"at":58,"level":1,"text":"Write a function that calls the functions above and gives back the answer."},{"at":64,"level":1,"text":"Write a function that calls the functions above and gives back the answer."}],"blanks":[{"line":9,"from":15,"to":20},{"line":16,"from":12,"to":17},{"line":18,"from":17,"to":18},{"line":19,"from":11,"to":32},{"line":22,"from":11,"to":18},{"line":25,"from":22,"to":45},{"line":28,"from":24,"to":26},{"line":30,"from":12,"to":35},{"line":43,"from":11,"to":17},{"line":46,"from":22,"to":45},{"line":48,"from":24,"to":26},{"line":50,"from":12,"to":39},{"line":55,"from":11,"to":17},{"line":58,"from":19,"to":56},{"line":64,"from":19,"to":56}]},"fn":{"slug":"base36","commit":"","header":"base36.h","name":"base36_test.cpp","test":"#include \"base36.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"encode_test\") { REQUIRE(base36::encode(\"test\", 5, 7) == \"41z4\"); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"encode_mixed_text\") {\n    REQUIRE(base36::encode(\"Hello, World 42\", 7, 11) == \"ydqq-bvbw-q6f1\");\n}\nTEST_CASE(\"encode_empty\") { REQUIRE(base36::encode(\"\", 1, 0).empty()); }\nTEST_CASE(\"encode_large_key\") { REQUIRE(base36::encode(\"a\", 35, 100) == \"2\"); }\nTEST_CASE(\"encode_long_text\") {\n    REQUIRE(base36::encode(\"the quick brown fox 2026\", 13, 5)\n            == \"ayv7-nb51-skhd-48hq-jtjz\");\n}\nTEST_CASE(\"encode_wraps_to_the_start\") {\n    REQUIRE(base36::encode(\"zz99\", 1, 1) == \"00aa\");\n}\nTEST_CASE(\"decode_test\") { REQUIRE(base36::decode(\"41z4\", 5, 7) == \"test\"); }\nTEST_CASE(\"decode_with_dashes\") {\n    REQUIRE(base36::decode(\"ydqq-bvbw-q6f1\", 7, 11) == \"helloworld42\");\n}\nTEST_CASE(\"decode_long_text\") {\n    REQUIRE(base36::decode(\"ayv7-nb51-skhd-48hq-jtjz\", 13, 5)\n            == \"thequickbrownfox2026\");\n}\nTEST_CASE(\"decode_empty\") { REQUIRE(base36::decode(\"\", 5, 0).empty()); }\nTEST_CASE(\"encode_even_a_throws\") {\n    REQUIRE_THROWS_AS(base36::encode(\"test\", 2, 1), std::invalid_argument);\n}\nTEST_CASE(\"decode_three_divides_a_throws\") {\n    REQUIRE_THROWS_AS(base36::decode(\"test\", 9, 1), std::invalid_argument);\n}\n#endif\n","setup":[],"calls":[{"call":"base36::encode(\"test\", 5, 7)","expected":"\"41z4\""}]}}}}
